-- Check how assessments relate to patients directly vs through encounters
SELECT COUNT(*) FROM assessmentbasics;
SELECT COUNT(DISTINCT pat_owner_ref) FROM assessmentbasics;
SELECT COUNT(*) FROM encounters;

-- Check if assessmentsymptomsandrisk.asr_key matches assessmentbasics.ab_key directly
SELECT asr.asr_key, ab.ab_key FROM assessmentsymptomsandrisk asr 
JOIN assessmentbasics ab ON asr.asr_key = ab.ab_key LIMIT 5;

-- Check if there's a way to determine "most recent" from assessmentbasics alone
-- Maybe using ab_key ordering?
SELECT pat_owner_ref, ab_key FROM assessmentbasics WHERE pat_owner_ref = 'P119424' ORDER BY ab_key;
